def brand_word_html(brand: str) -> str:
    """Render Bvonix with purple diamond accent on 'i'."""
    out = []
    for ch in brand:
        if ch.lower() == "i":
            out.append('<span class="dot-i"><span class="diamond-i" aria-hidden="true"></span>i</span>')
        else:
            out.append(ch)
    return "".join(out)
